<?php

namespace Database\Seeders;

use App\Models\Category;
use App\Models\Item;
use App\Models\Unit;
use Illuminate\Database\Seeder;

class InventoryDataSeeder extends Seeder
{
    /**
     * Menentukan item_type berdasarkan kode_barang SIMDA.
     */
    private function determineItemType(string $kodeBarang): string
    {
        // Kendaraan: 02.02.*
        if (str_starts_with($kodeBarang, '02.02.')) {
            return 'Kendaraan';
        }

        // Elektronik: Komputer, Printer, Scanner, dll
        if (str_starts_with($kodeBarang, '02.10.') || // Komputer & perangkat IT
            str_starts_with($kodeBarang, '02.06.') || // Kamera
            str_starts_with($kodeBarang, '02.08.') || // Stabilizer
            $kodeBarang === '02.05.01.05.043' ||       // LCD Projector
            $kodeBarang === '02.05.01.05.053' ||       // Layar LCD
            $kodeBarang === '02.05.02.06.002' ||       // Televisi
            $kodeBarang === '02.05.02.06.008' ||       // Sound System
            $kodeBarang === '02.05.02.06.018' ||       // Unit Power Supply
            $kodeBarang === '02.05.02.06.014' ||       // Microphone
            $kodeBarang === '02.05.01.01.004' ||       // Mesin Ketik Listrik
            $kodeBarang === '02.05.01.05.010' ||       // Alat Penghancur Kertas
            $kodeBarang === '02.05.01.05.012' ||       // Mesin Absensi
            $kodeBarang === '02.05.02.04.004' ||       // AC Split
            $kodeBarang === '02.05.02.04.006'          // Kipas Angin
        ) {
            return 'Elektronik';
        }

        // Mebeler: Meja, kursi, lemari, rak, dll
        if (str_starts_with($kodeBarang, '02.05.01.04.') || // Lemari, rak, filing cabinet
            str_starts_with($kodeBarang, '02.05.02.01.') || // Meja, kursi
            str_starts_with($kodeBarang, '02.05.03.')    || // Meja tamu, lemari perpustakaan
            $kodeBarang === '02.05.01.01.002'               // Mesin Ketik Manual
        ) {
            return 'Mebeler';
        }

        return 'Umum';
    }

    /**
     * Menentukan category berdasarkan kode_barang SIMDA.
     */
    private function determineCategoryCode(string $kodeBarang): string
    {
        if (str_starts_with($kodeBarang, '02.02.')) {
            return '1.1.5.9'; // Kendaraan Bermotor
        }

        if (str_starts_with($kodeBarang, '02.10.') ||
            str_starts_with($kodeBarang, '02.06.') ||
            str_starts_with($kodeBarang, '02.08.') ||
            $kodeBarang === '02.05.01.05.043' ||
            $kodeBarang === '02.05.01.05.053' ||
            $kodeBarang === '02.05.02.06.002' ||
            $kodeBarang === '02.05.02.06.008' ||
            $kodeBarang === '02.05.02.06.018' ||
            $kodeBarang === '02.05.02.06.014' ||
            $kodeBarang === '02.05.01.01.004' ||
            $kodeBarang === '02.05.01.05.010' ||
            $kodeBarang === '02.05.01.05.012' ||
            $kodeBarang === '02.05.02.04.004' ||
            $kodeBarang === '02.05.02.04.006'
        ) {
            return '1.1.5.8'; // Alat Elektronik
        }

        if (str_starts_with($kodeBarang, '02.05.')) {
            return '1.1.5.10'; // Mebeler
        }

        return '1.1.5.1'; // Barang Habis Pakai (default)
    }

    /**
     * Menentukan masa manfaat (tahun) berdasarkan item_type.
     */
    private function determineUsefulLife(string $itemType): ?int
    {
        return match($itemType) {
            'Kendaraan' => 8,
            'Elektronik' => 5,
            'Mebeler' => 10,
            default => null,
        };
    }

    /**
     * Membersihkan nilai string agar null jika kosong atau hanya berisi dash.
     */
    private function cleanValue(?string $value): ?string
    {
        if ($value === null) return null;
        $value = trim($value);
        if ($value === '' || $value === '-' || $value === '0') return null;
        return $value;
    }

    /**
     * Run the database seeds.
     */
    public function run(): void
    {
        // Pastikan satuan "unit" ada
        $unitUnit = Unit::firstOrCreate(['name' => 'unit']);

        // Pastikan semua kategori ada
        $categories = [];
        foreach (['1.1.5.1', '1.1.5.8', '1.1.5.9', '1.1.5.10'] as $code) {
            $categories[$code] = Category::where('code', $code)->first();
            if (!$categories[$code]) {
                $this->command->warn("Kategori dengan kode {$code} tidak ditemukan. Pastikan CategorySeeder sudah dijalankan.");
                return;
            }
        }

        $data = $this->getData();

        $count = 0;
        foreach ($data as $row) {
            $kodeBarang = $row['kode_barang'];
            $itemType = $this->determineItemType($kodeBarang);
            $categoryCode = $this->determineCategoryCode($kodeBarang);
            $usefulLife = $this->determineUsefulLife($itemType);

            $purchaseDate = null;
            if (!empty($row['tahun_perolehan']) && is_numeric($row['tahun_perolehan'])) {
                $purchaseDate = $row['tahun_perolehan'] . '-01-01';
            }

            Item::updateOrCreate(
                ['registration_number' => $row['nomor_urut_pendaftaran']],
                [
                    'asset_category'     => $row['kategori'],
                    'simda_code'         => $kodeBarang,
                    'name'               => $row['nama_barang'],
                    'register_number'    => $this->cleanValue($row['nomor_register']),
                    'brand_type'         => $this->cleanValue($row['merk_type']),
                    'size_spec'          => $this->cleanValue($row['ukuran_cc']),
                    'material'           => $this->cleanValue($row['bahan']),
                    'factory_number'     => $this->cleanValue($row['nomor_pabrik']),
                    'chassis_number'     => $this->cleanValue($row['nomor_rangka']),
                    'engine_number'      => $this->cleanValue($row['nomor_mesin']),
                    'license_plate'      => $this->cleanValue($row['nomor_polisi']),
                    'bpkb_number'        => $this->cleanValue($row['nomor_bpkb']),
                    'location'           => $this->cleanValue($row['ruang_lokasi']),
                    'acquisition_source' => $this->cleanValue($row['asal_usul']),
                    'description'        => $this->cleanValue($row['keterangan']),
                    'category_id'        => $categories[$categoryCode]->id,
                    'unit_id'            => $unitUnit->id,
                    'item_type'          => $itemType,
                    'unit_price'         => (float) $row['harga_rp'],
                    'stock'              => 1,
                    'purchase_date'      => $purchaseDate,
                    'useful_life'        => $usefulLife,
                    'residual_value'     => 0,
                ]
            );
            $count++;
        }

        $this->command->info("Berhasil import {$count} item inventaris.");
    }

